mapper.select:
SELECT order_flow_id FROM ${tableName}
WHERE if_current_link = '1'

    and order_id = #{orderId}

select count(*)
from  ${tableName} t
where 1 = 1

    and t.order_flow_id = #{orderFlowId}


    and t.order_id = #{orderId}


    and t.link_id = #{linkId}


    AND t.link_name = #{linkName}


    AND t.flow_record_name = #{flowRecordName}


    AND t.flow_node_time = #{flowNodeTime}


    AND t.process_id = #{processId}


    AND t.process_name = #{processName}


    AND t.if_timeout = #{ifTimeout}


    AND t.if_current_link = #{ifCurrentLink}


    AND t.delete_flag = #{deleteFlag}


    AND t.real_link_type = #{realLinkType}

SELECT * FROM ${tableName} t
where 1 = 1

    and t.order_id = #{orderId}


    AND t.if_current_link = #{ifCurrentLink}


    AND t.delete_flag = #{deleteFlag}


    and t.link_id = #{linkId}

SELECT d.process_name processName,
IF(d.flow_node_time IS NULL,'',DATE_FORMAT(d.flow_node_time,'%Y-%m-%d %H:%i:%s')) AS flowNodeTime,
IF(d.flow_end_time IS NULL,'',DATE_FORMAT(d.flow_end_time,'%Y-%m-%d %H:%i:%s')) AS flowEndTime,
d.remark,
d.close_remark AS closeRemark
FROM ${tableName} d
WHERE d.order_id = #{orderId}
AND d.link_id = #{linkId}
AND d.flow_node_time < #{nodeTime}
ORDER BY d.flow_node_time DESC LIMIT 1

select 
    from ${tableName} where order_id=#{orderId,jdbcType=VARCHAR}
 and flow_node_time > (select flow_node_time from ${tableName}
 where order_flow_id = #{orderFlowId,jdbcType=VARCHAR}) order by flow_node_time asc LIMIT 1

select if_current_link ifCurrentLink
from ${tableName} where order_id=#{orderId}
and link_id =#{linkId}

    and real_link_type =#{realLinkType}


    and enable_acceptance_mode =#{enableAcceptanceMode}

 order by flow_node_time desc LIMIT 1

select t.link_id linkId,t.link_name linkName,t.process_order_id processOrderId,t.approve_order_id approveOrderId,
       t.real_link_type realLinkType
from  ${tableName} t
where 1 = 1 AND t.if_current_link = '1'

    and t.order_flow_id = #{orderFlowId}


    and t.order_id = #{orderId}


    and t.link_id = #{linkId}


    AND t.link_name = #{linkName}


    AND t.flow_record_name = #{flowRecordName}


    AND t.flow_node_time = #{flowNodeTime}


    AND t.process_id = #{processId}


    AND t.process_name = #{processName}


    AND t.if_timeout = #{ifTimeout}


    AND t.delete_flag = #{deleteFlag}


    AND t.real_link_type = #{realLinkType}


    AND t.enable_acceptance_mode = #{enableAcceptanceMode}

order by t.flow_node_time desc
